import pandas as pddef select_best_spectra_by_Ca(input_csv, output_csv="best_Ca_spectra.csv"):    # Load the CSV    df = pd.read_csv(input_csv)    print(f"Loaded {len(df)} spectra")    # Convert Ha SNR to numeric (    df["SNR_Ca"] = pd.to_numeric(df["SNR_Ca"], errors="coerce")    # Remove rows where Ca SNR is missing    df = df.dropna(subset=["SNR_Ca"])    # Finding the index of the highest Li SNR for each target    best_indices = df.groupby("Target")["SNR_Ca"].idxmax()    # Select those rows    best_spectra = df.loc[best_indices]    # Sort by target    best_spectra = best_spectra.sort_values("Target")    # Save result    best_spectra.to_csv(output_csv, index=False)    print(f"Selected {len(best_spectra)} best spectra (one per target)")    print(f"Saved to {output_csv}")# Run itselect_best_spectra_by_Ca("Carmen_master_spectra.csv")